var svg=document.getElementById("pitch-svg");

/* === Startup-safe tool functions === */
function svgPt(cx,cy){
  var r=svg.getBoundingClientRect();
  var vb=svg.getAttribute("viewBox")||("0 0 "+W+" "+H);
  var vbParts=vb.split(" ").map(Number);
  var vbX=vbParts[0],vbY=vbParts[1],vbW=vbParts[2],vbH=vbParts[3];
  if(document.body.classList.contains("landscape")&&!document.body.classList.contains("desktop")){
    // Mobile landscape: SVG is rotated -90deg, remap coordinates
    var normX=(cx-r.left)/r.width;
    var normY=(cy-r.top)/r.height;
    return{x:vbX+normY*vbW, y:vbY+(1-normX)*vbH};
  }
  if(document.body.classList.contains("tt523-fs-rotated-desktop")){
    // v523: desktop fullscreen presentation rotation uses the same visual direction.
    var normX2=(cx-r.left)/r.width;
    var normY2=(cy-r.top)/r.height;
    return{x:vbX+normY2*vbW, y:vbY+(1-normX2)*vbH};
  }
  return{x:vbX+(cx-r.left)/r.width*vbW, y:vbY+(cy-r.top)/r.height*vbH};
}

function clamp(v,lo,hi){return Math.max(lo,Math.min(hi,v));}

function moveDrag(nx,ny){
  nx=clamp(nx,10,W-10);
  ny=clamp(ny,10,H-10);
  if(!dragging)return;
  if(dragging.type==="ball"){
    ball.x=nx;ball.y=ny;
    var bg=svg.querySelector(".ball-token");
    if(bg){
      var t=bg.querySelector("text"),h=bg.querySelector("circle");
      if(t){t.setAttribute("x",nx);t.setAttribute("y",ny);}
      if(h){h.setAttribute("cx",nx);h.setAttribute("cy",ny);}
    }
  }else if(dragging.type==="player"){
    var movedPlayer=null;
    for(var i=0;i<players.length;i++)if(players[i].id===dragging.id){players[i].x=nx;players[i].y=ny;movedPlayer=players[i];break;}
    var g=svg.querySelector(".player-token[data-id='"+dragging.id+"']");
    if(g){
      var c=g.querySelector("circle"),t=g.querySelector("text.token-text")||g.querySelector("text");
      if(c){c.setAttribute("cx",nx);c.setAttribute("cy",ny);}
      if(t){t.setAttribute("x",nx);t.setAttribute("y",ny);}

      /* v422: Taktikfilm/truppvisning – flytta även namn/tröja direkt under drag.
         v415 lade namn/tröja som extra SVG-noder ovanpå den befintliga spelarsymbolen.
         Den vanliga moveDrag flyttade bara cirkel + nummertext, vilket gjorde att namnet
         försvann/stannade kvar tills render() kördes på mouseup/touchend. */
      try{
        var squadId=movedPlayer&&(movedPlayer.squadPlayerId||movedPlayer.truppId||movedPlayer.squadId);
        var showAsJersey=document.body.classList.contains('tt415-taktik-jersey');
        var jersey=g.querySelector('path.tt415-jersey');
        if(jersey){
          jersey.setAttribute('d',['M',nx-18,ny-12,'L',nx-9,ny-22,'L',nx-3,ny-16,'L',nx+3,ny-16,'L',nx+9,ny-22,'L',nx+18,ny-12,'L',nx+13,ny-3,'L',nx+10,ny-6,'L',nx+10,ny+18,'L',nx-10,ny+18,'L',nx-10,ny-6,'L',nx-13,ny-3,'Z'].join(' '));
        }
        var nl=g.querySelector('text.tt415-squad-name-label');
        if(squadId && movedPlayer && movedPlayer.name){
          if(!nl){
            nl=document.createElementNS('http://www.w3.org/2000/svg','text');
            nl.setAttribute('class','tt415-squad-name-label');
            nl.setAttribute('text-anchor','middle');
            nl.setAttribute('dominant-baseline','central');
            nl.setAttribute('font-weight','800');
            nl.setAttribute('paint-order','stroke');
            g.appendChild(nl);
          }
          nl.setAttribute('x',nx);
          nl.setAttribute('y',ny+(showAsJersey?31:28));
          nl.textContent=movedPlayer.name||'';
        }else if(nl){
          nl.remove();
        }
      }catch(e){}
    }
  }else if(dragging.type==="label"){
    var lab=null;
    for(var j=0;j<labels.length;j++){
      if(labels[j].id===dragging.id){labels[j].x=nx;labels[j].y=ny;lab=labels[j];break;}
    }
    /* v395: flytta textrutan visuellt direkt under drag, inte först när man släpper. */
    if(lab){
      updateLabelSvgPosition(lab,nx,ny);
    }
  }
}

