/* === v275-match-empty-lineup-dialog-and-alpha-list ===
   Bas: v274.
   Smal fix:
   1) Om man försöker skapa laguppställning från Match utan valda spelare visas dialogruta.
   2) Matcher → Match-listan sorteras alfabetiskt på namn.
   Rör inte sparade matcher, mål, plan-döljning, laguppställning eller Supabase.
*/
(function(){
  if(window.__tt275MatchDialogAlphaList)return;
  window.__tt275MatchDialogAlphaList=true;

  function setVersion275(){
    try{
      var ids=['version','app-version','version-label','app-version-label'];
      ids.forEach(function(id){var el=document.getElementById(id);if(el)el.textContent='680 TEST';});
      document.querySelectorAll('[data-version],.version,.app-version,.version-label,.app-version-label,#version,#app-version,#version-label,#app-version-label,#ver,#build-version').forEach(function(el){
        var t=String(el.textContent||'').trim();
        if(/^(v?\d+|v3\.)$/i.test(t))el.textContent='680 TEST';
      });
    }catch(e){}
  }

  function selectedStartPlayers275(){
    try{
      return (trupp||[]).filter(function(sp){return (matchSelections||{})[sp.id]==='start';});
    }catch(e){return [];}
  }

  function installEmptyLineupGuard275(){
    var btn=document.getElementById('btn-match-to-taktik');
    if(!btn || btn._tt275EmptyGuard)return;
    btn._tt275EmptyGuard=true;
    btn.addEventListener('click',function(e){
      try{
        if(!selectedStartPlayers275().length){
          e.preventDefault();
          e.stopPropagation();
          if(typeof e.stopImmediatePropagation==='function')e.stopImmediatePropagation();
          if(typeof showToast==='function')showToast('Du har inte valt några spelare.',false);
          alert('Du har inte valt några spelare. Välj minst en spelare i Match-listan innan du skapar laguppställning.');
          return false;
        }
      }catch(err){}
    },true);
  }

  function playerAlpha275(a,b){
    var an=String((a&&a.namn)||'').trim();
    var bn=String((b&&b.namn)||'').trim();
    var c=an.localeCompare(bn,'sv',{sensitivity:'base'});
    if(c!==0)return c;
    return ((a&&a.nr)||0)-((b&&b.nr)||0);
  }

  function safeMatchCount275(sp){
    try{return getPlayerMatchCount(sp.id)||0;}catch(e){return 0;}
  }

  function renderMatchTruppList275(){
    var list=document.getElementById('match-trupp-list');
    if(!list)return;
    list.innerHTML='';

    var nSelected=0;
    try{
      nSelected=Object.values(matchSelections||{}).filter(function(v){return v==='start' || v==='avbytare';}).length;
    }catch(e){}
    var counter=document.getElementById('match-counter');
    if(counter)counter.textContent=nSelected+' vald'+(nSelected===1?'':'a');

    var sorted=(trupp||[]).slice().sort(playerAlpha275);
    if(!sorted.length){
      list.innerHTML='<span style="color:#7aaa88;font-size:0.8rem">Lägg till spelare i truppen först</span>';
      return;
    }

    sorted.forEach(function(sp){
      var sel=(matchSelections||{})[sp.id]||null;
      var row=document.createElement('div');
      row.className='row'+(sel==='start'?' tt293-match-row-selected':'');
      row.style.cssText='padding:4px 8px;border-radius:7px;border:1px solid '+(sel==='start'?'rgba(74,232,122,0.45)':'transparent')+';background:'+(sel==='start'?'rgba(74,232,122,0.15)':'transparent')+';box-shadow:'+(sel==='start'?'inset 3px 0 0 rgba(74,232,122,0.75)':'none')+';transition:background .12s ease,border-color .12s ease,box-shadow .12s ease';

      var nr=document.createElement('span');
      nr.style.cssText='font-weight:900;color:#4ae87a;min-width:24px;font-size:0.82rem';
      nr.textContent='#'+(sp.nr||'');

      var nm=document.createElement('span');
      nm.style.cssText='flex:1;font-size:0.82rem;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap';
      nm.textContent=sp.namn||'';

      var cntEl=document.createElement('span');
      cntEl.style.cssText='font-size:0.68rem;color:#7aaa88;white-space:nowrap';
      cntEl.textContent=safeMatchCount275(sp)+' mat.';

      var btnS=document.createElement('button');
      btnS.className='btn'+(sel==='start'?' on':'');
      btnS.style.cssText='padding:2px 7px;font-size:0.65rem';
      btnS.textContent='Start';
      btnS.addEventListener('click',function(){
        matchSelections[sp.id]=sel==='start'?null:'start';
        renderMatchTruppList275();
      });

      row.appendChild(nr);
      row.appendChild(nm);
      row.appendChild(cntEl);
      row.appendChild(btnS);
      list.appendChild(row);
    });
  }

  function apply275(){
    setVersion275();
    installEmptyLineupGuard275();
    try{
      renderMatchTruppList=renderMatchTruppList275;
      window.renderMatchTruppList=renderMatchTruppList275;
      var p=document.getElementById('lag-match');
      if(p && p.style.display!=='none')renderMatchTruppList275();
    }catch(e){}
  }

  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply275);
  else apply275();
  setTimeout(apply275,100);
  setTimeout(apply275,600);
  setTimeout(setVersion275,1600);
  window.tt275RenderMatchTruppList=renderMatchTruppList275;
})();
/* === slut v275-match-empty-lineup-dialog-and-alpha-list === */

/* === v276-autosave-match-before-lineup ===
   Bas: v275 + rensad index.
   Syfte:
   - Om man väljer spelare i Matcher → Match och går direkt till laguppställning
     utan att först trycka Spara match, skapas matchen automatiskt först.
   - Då får laguppställningens Spara ett riktigt match-id att uppdatera.
   - Om inga spelare är valda lämnas v275-dialogen/varningen kvar.
   - Rör inte Sparade matcher, statistik, plan-döljning eller taktikfilm.
*/
(function(){
  if(window.__tt276AutoSaveMatchBeforeLineup)return;
  window.__tt276AutoSaveMatchBeforeLineup=true;

  function setVersion276(){
    try{
      var ids=['version','app-version','version-label','app-version-label','ver','build-version'];
      ids.forEach(function(id){var el=document.getElementById(id);if(el)el.textContent='680 TEST';});
      document.querySelectorAll('[data-version],.version,.app-version,.version-label,.app-version-label,#version,#app-version,#version-label,#app-version-label,#ver,#build-version').forEach(function(el){
        var t=String(el.textContent||'').trim();
        if(/^(v?\d+|v3\.)$/i.test(t))el.textContent='680 TEST';
      });
    }catch(e){}
  }

  function clone276(o){
    try{return JSON.parse(JSON.stringify(o||{}));}catch(e){return o;}
  }

  function selectedIds276(kind){
    var out=[];
    try{
      (trupp||[]).forEach(function(sp){
        if(matchSelections && matchSelections[sp.id]===kind)out.push(sp.id);
      });
    }catch(e){}
    return out;
  }

  function selectedStartPlayers276(){
    try{return (trupp||[]).filter(function(sp){return (matchSelections||{})[sp.id]==='start';});}
    catch(e){return [];}
  }

  function buildAutoMatch276(){
    var datumEl=document.getElementById('match-datum');
    var motEl=document.getElementById('match-motstand');
    var datum=datumEl ? String(datumEl.value||'').trim() : '';
    var motstand=motEl ? String(motEl.value||'').trim() : '';

    if(!datum){
      try{showToast('Välj datum först.',false);}catch(e){}
      alert('Välj datum innan du skapar laguppställning.');
      return null;
    }

    var match={
      datum:datum,
      motstand:motstand || 'Okänd',
      startade:selectedIds276('start'),
      avbytare:selectedIds276('avbytare'),
      uppstallningar:clone276(matchVariants||[]),
      // Ny osparad match ska börja 0–0. Befintliga matcher går inte genom autosparflödet.
      mal_hemma:0,
      mal_borta:0
    };
    return match;
  }

  function syncLocalMatch276(match){
    try{
      if(!Array.isArray(matcher))matcher=[];
      var idx=matcher.findIndex(function(x){return String(x.dbId)===String(match.dbId);});
      if(idx>=0)matcher[idx]=match;
      else matcher.push(match);
    }catch(e){}
  }

  function saveNewMatch276(match){
    var payloadData;
    try{payloadData=(typeof addMetaToData==='function') ? addMetaToData(match) : match;}
    catch(e){payloadData=match;}

    var body={
      name:match.datum+' '+match.motstand,
      data:payloadData,
      type:'match',
      folder:'Allmänt'
    };

    try{cloudStatus('Sparar match...','#7aaa88');}catch(e){}

    return fetch(SUPA_URL+'/rest/v1/'+SUPA_TABLE,{
      method:'POST',
      headers:Object.assign({},supaHeaders(),{'Prefer':'return=representation'}),
      body:JSON.stringify(body)
    }).then(function(r){
      if(!r.ok)throw new Error('HTTP '+r.status);
      return r.json();
    }).then(function(data){
      if(!data || !data[0] || !data[0].id)throw new Error('Matchen kunde inte sparas');
      match.dbId=data[0].id;
      window._editingMatchId=match.dbId;
      syncLocalMatch276(match);
      try{if(typeof renderSparadeMatcherList==='function')renderSparadeMatcherList();}catch(e){}
      try{if(typeof renderStatistik==='function')renderStatistik();}catch(e){}
      try{if(typeof renderMatchHistory==='function')renderMatchHistory();}catch(e){}
      try{cloudStatus('✅ Match skapad','#4ae87a');}catch(e){}
      return match;
    });
  }

  function installAutoSave276(){
    var btn=document.getElementById('btn-match-to-taktik');
    if(!btn || btn._tt276AutoSaveBound)return;
    btn._tt276AutoSaveBound=true;

    btn.addEventListener('click',function(e){
      try{
        if(window.__tt276AllowOriginalLineupClick)return;

        // Redan sparad/redigerad match: låt befintligt laguppställningsflöde köra som vanligt.
        if(window._editingMatchId)return;

        var selected=selectedStartPlayers276();
        if(!selected.length){
          // v275-guard visar dialogen. Fallback om den av någon anledning inte hinner.
          e.preventDefault();
          e.stopPropagation();
          if(e.stopImmediatePropagation)e.stopImmediatePropagation();
          try{showToast('Du har inte valt några spelare.',false);}catch(err){}
          alert('Du har inte valt några spelare. Välj minst en spelare i Match-listan innan du skapar laguppställning.');
          return false;
        }

        e.preventDefault();
        e.stopPropagation();
        if(e.stopImmediatePropagation)e.stopImmediatePropagation();

        if(btn._tt276Saving){
          try{showToast('Sparar match – vänta...',false);}catch(err){}
          return false;
        }

        var match=buildAutoMatch276();
        if(!match)return false;

        btn._tt276Saving='1';
        saveNewMatch276(match).then(function(saved){
          btn._tt276Saving='';
          try{showToast('Match skapad – öppnar laguppställning');}catch(err){}
          // Låt den befintliga, vältestade laguppställningskoden göra själva öppningen.
          window.__tt276AllowOriginalLineupClick=true;
          setTimeout(function(){
            try{btn.click();}finally{setTimeout(function(){window.__tt276AllowOriginalLineupClick=false;},0);}
          },0);
        }).catch(function(err){
          btn._tt276Saving='';
          try{cloudStatus('❌ Fel: '+err.message,'#e84a4a');}catch(e2){}
          try{showToast('Kunde inte skapa match',false);}catch(e2){}
        });

        return false;
      }catch(err){}
    },true);
  }

  function apply276(){
    setVersion276();
    installAutoSave276();
  }

  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply276);
  else apply276();
  setTimeout(apply276,100);
  setTimeout(apply276,700);
  setTimeout(setVersion276,1600);
})();
/* === slut v276-autosave-match-before-lineup === */


/* === v278-team-scoped-matcher-clean ===
   Bas: v276 fungerande Matcher.
   Syfte: lagisolera Trupp och Matcher utan att röra planlayout/laguppställningsflöde.
   Viktigt:
   - gamla trupp-/matchrader utan teamId/teamCode ignoreras
   - ingen migrering/adoption av gamla filer
   - match/trupp-data laddas om efter gamla startladdningar, så fel lag inte ligger kvar i minnet
*/
(function(){
  if(window.__tt278TeamScopedMatcherClean)return;
  window.__tt278TeamScopedMatcherClean=true;

  function norm(v){return String(v||'').trim().toLowerCase();}
  function profile(){
    try{ if(typeof getUserProfile==='function'){var p=getUserProfile(); if(p)return p;} }catch(e){}
    try{ if(typeof getProfileSafeV10==='function'){var p2=getProfileSafeV10(); if(p2)return p2;} }catch(e){}
    try{ var raw=localStorage.getItem('tt_profile_v1'); return raw?JSON.parse(raw):null; }catch(e){}
    return null;
  }
  function active(){
    var p=profile();
    if(!p)return null;
    var keys=[];
    [p.teamId,p.teamCode].forEach(function(v){v=norm(v); if(v && keys.indexOf(v)<0)keys.push(v);});
    if(!keys.length)return null;
    return {
      profile:p,
      keys:keys,
      teamId:p.teamId||p.teamCode,
      teamCode:p.teamCode||p.teamId,
      teamName:p.teamName||p.teamCode||p.teamId,
      ownerId:p.ownerId||'',
      ownerName:p.ownerName||''
    };
  }
  function meta(obj){
    if(!obj)return {};
    return obj._meta || obj.meta || (obj.data&&obj.data._meta) || {};
  }
  function dataKeys(obj){
    var m=meta(obj), out=[];
    [m.teamId,m.teamCode,obj&&obj.teamId,obj&&obj.teamCode].forEach(function(v){
      v=norm(v); if(v && out.indexOf(v)<0)out.push(v);
    });
    return out;
  }
  function belongs(obj){
    var a=active(); if(!a)return false;
    var ks=dataKeys(obj);
    if(!ks.length)return false; // legacy utan lag-id/kod visas inte
    return ks.some(function(k){return a.keys.indexOf(k)>=0;});
  }
  function withTeamData(obj){
    var a=active();
    var d;
    try{d=JSON.parse(JSON.stringify(obj||{}));}catch(e){d=obj||{};}
    if(!a)return d;
    d._meta=d._meta||{};
    d._meta.teamId=a.teamId;
    d._meta.teamCode=a.teamCode;
    d._meta.teamName=a.teamName;
    if(a.ownerName)d._meta.updatedBy=a.ownerName;
    if(a.ownerId)d._meta.updatedById=a.ownerId;
    if(!d._meta.createdBy && a.ownerName)d._meta.createdBy=a.ownerName;
    if(!d._meta.createdById && a.ownerId)d._meta.createdById=a.ownerId;
    d._meta.updatedAt=new Date().toISOString();
    return d;
  }
  function setVersion(){
    try{
      var ids=['version','app-version','version-label','app-version-label','ver','build-version'];
      ids.forEach(function(id){var el=document.getElementById(id);if(el)el.textContent='680 TEST';});
      document.querySelectorAll('[data-version],.version,.app-version,.version-label,.app-version-label,#version,#app-version,#version-label,#app-version-label,#ver,#build-version').forEach(function(el){
        var t=String(el.textContent||'').trim();
        if(/^(v?\d+|v3\.)$/i.test(t))el.textContent='680 TEST';
      });
    }catch(e){}
  }
  function rowName(type){
    var a=active();
    return type+' '+(a?(a.teamCode||a.teamId):'utan-lag');
  }
  function resetMatchMemory(){
    try{matcher=[];}catch(e){}
    try{trupp=[];}catch(e){}
    try{matchSelections={};}catch(e){}
    try{matchRoster=[];}catch(e){}
    try{matchAssignments={};}catch(e){}
    try{matchVariants=[];activeVariantIdx=0;}catch(e){}
    try{matchGoals={home:0,away:0}; if(typeof updateGoalDisplay==='function')updateGoalDisplay();}catch(e){}
    try{window._editingMatchId=null;}catch(e){}
  }
  function renderAllMatchViews(){
    try{if(typeof renderTruppList==='function')renderTruppList();}catch(e){}
    try{if(typeof renderMatchTruppList==='function')renderMatchTruppList();}catch(e){}
    try{if(typeof renderSparadeMatcherList==='function')renderSparadeMatcherList();}catch(e){}
    try{if(typeof renderStatistik==='function')renderStatistik();}catch(e){}
  }

  // Säkerhetsnät: alla befintliga match-/trupp-sparvägar får lagmetadata utan att vi skriver om flödena.
  if(!window.__tt278FetchWrapped){
    window.__tt278FetchWrapped=true;
    var oldFetch=window.fetch;
    window.fetch=function(input,init){
      try{
        var url=String(input&&input.url?input.url:input||'');
        if(init && init.body && url.indexOf(SUPA_TABLE)>=0){
          var body=JSON.parse(init.body);
          var t=body && body.type;
          if((t==='match' || t==='trupp') && body.data){
            body.data=withTeamData(body.data);
            if(!body.name)body.name=rowName(t);
            init=Object.assign({},init,{body:JSON.stringify(body)});
          }
        }
      }catch(e){}
      return oldFetch.apply(this,arguments.length? [input,init] : arguments);
    };
  }

  window.saveTrupp=function(){
    var a=active();
    if(!a){try{showToast('Saknar lagkod – truppen sparades inte');}catch(e){} return;}
    var payload=withTeamData({trupp:trupp||[]});
    return fetch(SUPA_URL+'/rest/v1/'+SUPA_TABLE+'?type=eq.trupp&order=id.desc',{headers:supaHeaders()})
      .then(function(r){return r.json();})
      .then(function(rows){
        rows=Array.isArray(rows)?rows:[];
        var existing=rows.find(function(row){return row && row.data && belongs(row.data);});
        var body={name:rowName('trupp'),data:payload,type:'trupp',folder:'Allmänt'};
        if(existing && existing.id){
          return fetch(SUPA_URL+'/rest/v1/'+SUPA_TABLE+'?id=eq.'+existing.id,{method:'PATCH',headers:Object.assign({},supaHeaders(),{'Prefer':'return=representation'}),body:JSON.stringify(body)});
        }
        return fetch(SUPA_URL+'/rest/v1/'+SUPA_TABLE,{method:'POST',headers:Object.assign({},supaHeaders(),{'Prefer':'return=representation'}),body:JSON.stringify(body)});
      })
      .catch(function(err){try{cloudStatus('❌ Truppfel: '+err.message,'#e84a4a');}catch(e){}});
  };

  window.loadTrupp=function(){
    var a=active();
    if(!a){trupp=[];renderAllMatchViews();return Promise.resolve([]);}
    return fetch(SUPA_URL+'/rest/v1/'+SUPA_TABLE+'?type=eq.trupp&order=id.desc',{headers:supaHeaders()})
      .then(function(r){return r.json();})
      .then(function(rows){
        rows=Array.isArray(rows)?rows:[];
        var row=rows.find(function(x){return x && x.data && belongs(x.data);});
        trupp=(row && row.data && Array.isArray(row.data.trupp)) ? row.data.trupp : [];
        renderAllMatchViews();
        return trupp;
      })
      .catch(function(){trupp=[];renderAllMatchViews();return [];});
  };

  window.loadMatcher=function(){
    var a=active();
    if(!a){matcher=[];renderAllMatchViews();return Promise.resolve([]);}
    return fetch(SUPA_URL+'/rest/v1/'+SUPA_TABLE+'?type=eq.match&order=id.desc',{headers:supaHeaders()})
      .then(function(r){return r.json();})
      .then(function(rows){
        matcher=[];
        rows=Array.isArray(rows)?rows:[];
        rows.forEach(function(row){
          var m=row && row.data ? row.data : null;
          if(!m || !belongs(m))return;
          m.dbId=row.id;
          matcher.push(m);
        });
        renderAllMatchViews();
        return matcher;
      })
      .catch(function(){matcher=[];renderAllMatchViews();return [];});
  };

  function reloadScoped(){
    resetMatchMemory();
    renderAllMatchViews();
    try{window.loadTrupp();}catch(e){}
    try{window.loadMatcher();}catch(e){}
  }
  window.tt278ReloadScopedMatcherData=reloadScoped;

  // Kör efter gamla startladdningar så fel lag inte ligger kvar i minnet.
  function boot(){setVersion(); reloadScoped();}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);
  else setTimeout(boot,0);
  setTimeout(boot,500);
  setTimeout(boot,1800);

  // Vid profil-/lagbyte: ladda om matchdata för nya laget.
  var last='';
  function currentKey(){var a=active();return a?a.keys.join('|'):'';}
  function checkTeamChanged(){
    var k=currentKey();
    if(!last){last=k;return;}
    if(k && k!==last){last=k;reloadScoped();}
  }
  last=currentKey();
  window.addEventListener('storage',function(e){if(e && e.key==='tt_profile_v1')setTimeout(function(){last='';reloadScoped();},0);});
  document.addEventListener('visibilitychange',function(){if(!document.hidden)checkTeamChanged();});
  document.addEventListener('click',function(){setTimeout(checkTeamChanged,100);setTimeout(checkTeamChanged,700);},true);
  setTimeout(setVersion,2600);
})();
/* === slut v278-team-scoped-matcher-clean === */


/* === v291-taktikfilm-compact-draw-options ===
   Bas: stabil v278.
   Syfte:
   - En enda central styrning för ritvalspanelerna:
     Tavla vanligt läge, Tavla helskärm, Taktikfilm och Matcher.
   - Taktikfilm visar ritval uppe till vänster på planen, inte i nedersta menyn.
   - Gamla v248/v252-rader får inte längre gömma/flytta panelerna i Taktikfilm/helskärm.
   Rör inte Matcher, Trupp, lagkoppling, taktikfilms-sparning eller uppspelning. */
(function(){
  if(window.__tt291CentralDrawOptionsCompactHeight)return;
  window.__tt291CentralDrawOptionsCompactHeight=true;

  var OPTION_IDS=['arrow-options','freehand-options','zone-options'];
  var TOOL_TO_OPTION={arrow:'arrow-options',freehand:'freehand-options',zone:'zone-options'};

  function setVersion291(){
    try{
      ['version','app-version','version-label','app-version-label','ver','build-version'].forEach(function(id){
        var el=document.getElementById(id); if(el)el.textContent='680 TEST';
      });
      document.querySelectorAll('[data-version],.version,.app-version,.version-label,.app-version-label,#version,#app-version,#version-label,#app-version-label,#ver,#build-version').forEach(function(el){
        var t=String(el.textContent||'').trim();
        if(/^(v?\d+|v3\.)$/i.test(t))el.textContent='680 TEST';
      });
    }catch(e){}
  }

  function isTaktikActive291(){
    try{
      if(document.querySelector('.tab.on[data-panel="taktik"]'))return true;
      var p=document.getElementById('panel-taktik');
      if(p && p.classList.contains('on'))return true;
      if(typeof playback!=='undefined' && playback)return true;
      if(typeof isEditingTaktik!=='undefined' && isEditingTaktik)return true;
      if(typeof editingTaktikIdx!=='undefined' && editingTaktikIdx!==null)return true;
    }catch(e){}
    return false;
  }

  function isMatcherActive291(){
    try{
      if(document.querySelector('.tab.on[data-panel="lag"]'))return true;
      var p=document.getElementById('panel-lag');
      return !!(p && p.classList.contains('on'));
    }catch(e){return false;}
  }

  function activeOptionId291(){
    try{return TOOL_TO_OPTION[mode]||null;}catch(e){return null;}
  }

  function injectStyle291(){
    if(document.getElementById('tt291-central-draw-options-style'))return;
    var st=document.createElement('style');
    st.id='tt291-central-draw-options-style';
    st.textContent=[
      '#pitch-wrapper{position:relative}',
      '#tt291-plan-draw-options{display:none;position:absolute;left:10px;top:10px;z-index:12000;max-width:calc(100% - 20px);box-sizing:border-box;align-items:flex-start;gap:2px;pointer-events:none}',
      'body.fullscreen-portrait #tt291-plan-draw-options{position:fixed;left:6px;top:calc(env(safe-area-inset-top,0px) + 48px);max-width:calc(100vw - 12px);z-index:12000}',
      '@media (max-width: 700px){body.tt291-taktik-active:not(.fullscreen-portrait) #tt291-plan-draw-options{position:fixed;left:4px;top:var(--tt291-draw-options-mobile-top,68px);width:min-content;max-width:min(74vw,260px);z-index:12000}}',
      '@media (max-width: 900px){body.tt291-taktik-active:not(.fullscreen-portrait) #tt291-plan-draw-options #arrow-options,body.tt291-taktik-active:not(.fullscreen-portrait) #tt291-plan-draw-options #freehand-options,body.tt291-taktik-active:not(.fullscreen-portrait) #tt291-plan-draw-options #zone-options{padding:1px 3px!important;border-radius:6px!important;gap:2px!important;font-size:9px!important;line-height:1!important;max-width:min(74vw,260px)!important;min-height:0!important}body.tt291-taktik-active:not(.fullscreen-portrait) #tt291-plan-draw-options select,body.tt291-taktik-active:not(.fullscreen-portrait) #tt291-plan-draw-options button{min-height:17px!important;height:17px!important;font-size:9px!important;line-height:1!important;max-width:72px!important;padding:0 2px!important;margin:0!important;border-radius:4px!important}body.tt291-taktik-active:not(.fullscreen-portrait) #tt291-plan-draw-options label,body.tt291-taktik-active:not(.fullscreen-portrait) #tt291-plan-draw-options span{font-size:9px!important;line-height:1!important;margin:0!important;padding:0!important}}',
      'body.tt291-taktik-active:not(.fullscreen-portrait) #tt291-plan-draw-options{display:flex}',
      'body.fullscreen-portrait #tt291-plan-draw-options{display:flex}',
      '#tt291-plan-draw-options #arrow-options,#tt291-plan-draw-options #freehand-options,#tt291-plan-draw-options #zone-options{position:static!important;left:auto!important;right:auto!important;top:auto!important;bottom:auto!important;transform:none!important;z-index:auto!important;margin:0!important;width:max-content!important;max-width:min(74vw,260px)!important;overflow-x:auto!important;overflow-y:hidden!important;-webkit-overflow-scrolling:touch!important;box-sizing:border-box!important;background:rgba(17,26,20,.94)!important;border:1px solid #2d4a35!important;border-radius:6px!important;padding:1px 3px!important;box-shadow:0 2px 8px rgba(0,0,0,.28)!important;gap:2px!important;align-items:center!important;pointer-events:auto!important;font-size:9px!important;line-height:1!important;white-space:nowrap!important}',
      '#tt291-plan-draw-options #arrow-options:not(.tt291-active-option),#tt291-plan-draw-options #freehand-options:not(.tt291-active-option),#tt291-plan-draw-options #zone-options:not(.tt291-active-option){display:none!important}',
      '#tt291-plan-draw-options .tt291-active-option{display:flex!important}',
      '#tt291-plan-draw-options select,#tt291-plan-draw-options button{min-height:17px!important;height:17px!important;font-size:9px!important;line-height:1!important;max-width:72px!important;padding:0 2px!important;margin:0!important;border-radius:4px!important;pointer-events:auto!important;touch-action:auto!important}',
      '#tt291-plan-draw-options label,#tt291-plan-draw-options span{font-size:9px!important;line-height:1!important;margin:0!important;padding:0!important}',

      'body.tt291-matcher-active #arrow-options,body.tt291-matcher-active #freehand-options,body.tt291-matcher-active #zone-options{display:none!important}',
      'body.tt291-taktik-active:not(.fullscreen-portrait) #tt252-ipad-rita-row #arrow-options,body.tt291-taktik-active:not(.fullscreen-portrait) #tt252-ipad-rita-row #freehand-options,body.tt291-taktik-active:not(.fullscreen-portrait) #tt252-ipad-rita-row #zone-options{display:none!important}'
    ].join('\n');
    document.head.appendChild(st);
  }

  function planContainer291(){
    var c=document.getElementById('tt291-plan-draw-options');
    if(c)return c;
    c=document.createElement('div');
    c.id='tt291-plan-draw-options';
    var pw=document.getElementById('pitch-wrapper') || document.body;
    pw.appendChild(c);
    return c;
  }

  function normalRow291(){
    return document.getElementById('tt252-ipad-rita-row') ||
           document.querySelector('.tt248-tavla-rita-row') ||
           (document.getElementById('btn-arrow') && document.getElementById('btn-arrow').parentNode) ||
           document.getElementById('topbar') || document.body;
  }

  function setPanelVisible291(el,show){
    if(!el)return;
    if(show){
      el.classList.add('tt291-active-option');
      el.style.setProperty('display','flex','important');
    }else{
      el.classList.remove('tt291-active-option');
      el.style.setProperty('display','none','important');
    }
  }

  function updateMobileTop291(){
    try{
      var topbar=document.getElementById('topbar');
      if(!topbar)return;
      var rect=topbar.getBoundingClientRect();
      var y=Math.max(0, Math.ceil(rect.bottom));
      document.documentElement.style.setProperty('--tt291-draw-options-mobile-top', y+'px');
    }catch(e){}
  }

  function tt678DesktopTaktikfilmRitvalOwnerActive291(){
    try{
      if(!(window.matchMedia && window.matchMedia('(min-width:1024px) and (pointer:fine)').matches))return false;
      if(document.body && document.body.classList.contains('fullscreen-portrait'))return false;
      var edit=document.getElementById('edit-taktik-ui');
      var bar=document.getElementById('taktikbar');
      var panel=document.getElementById('panel-taktik');
      var editVisible=!!(edit && getComputedStyle(edit).display!=='none' && getComputedStyle(edit).visibility!=='hidden');
      var barVisible=!!(bar && getComputedStyle(bar).display!=='none' && getComputedStyle(bar).visibility!=='hidden');
      var panelActive=!!((panel && panel.classList.contains('on')) || document.querySelector('.tab.on[data-panel="taktik"]'));
      return !!(panelActive && editVisible && barVisible);
    }catch(e){return false;}
  }

  function update291(){
    try{
      setVersion291();
      injectStyle291();
      updateMobileTop291();

      // v679: i Taktikfilm desktop äger indexets v679-script ritvalsplaceringen.
      // Den gamla v291-panelen ska då inte flytta eller gömma arrow/freehand/zone-options.
      if(tt678DesktopTaktikfilmRitvalOwnerActive291()){
        document.body.classList.add('tt291-taktik-active');
        document.body.classList.remove('tt291-plane-options');
        var oldPlane678=document.getElementById('tt291-plan-draw-options');
        if(oldPlane678)oldPlane678.style.setProperty('display','none','important');
        return;
      }

      var taktik=isTaktikActive291();
      var fs=document.body.classList.contains('fullscreen-portrait');
      var matcher=isMatcherActive291();
      var activeOpt=activeOptionId291();
      var planeMode=(fs || taktik) && !matcher && !!activeOpt;
      document.body.classList.toggle('tt291-taktik-active',!!taktik);
      document.body.classList.toggle('tt291-matcher-active',!!matcher);
      document.body.classList.toggle('tt291-plane-options',!!planeMode);

      var plane=planContainer291();
      if(planeMode){
        OPTION_IDS.forEach(function(id){
          var el=document.getElementById(id); if(!el)return;
          if(el.parentNode!==plane)plane.appendChild(el);
          setPanelVisible291(el,id===activeOpt);
        });
        plane.style.setProperty('display','flex','important');
      }else{
        plane.style.setProperty('display','none','important');
        var row=normalRow291();
        OPTION_IDS.forEach(function(id){
          var el=document.getElementById(id); if(!el)return;
          if(el.parentNode===plane && row)row.appendChild(el);
          if(matcher || taktik || fs || !activeOpt)setPanelVisible291(el,false);
          else setPanelVisible291(el,id===activeOpt);
        });
      }
    }catch(e){}
  }

  function schedule291(){
    update291();
    setTimeout(update291,0);
    setTimeout(update291,90);
    setTimeout(update291,230);
  }

  var oldSetMode291=typeof setMode==='function'?setMode:null;
  if(oldSetMode291 && !oldSetMode291.__tt291Wrapped){
    var wrappedSetMode291=function(){
      var res=oldSetMode291.apply(this,arguments);
      schedule291();
      return res;
    };
    wrappedSetMode291.__tt291Wrapped=true;
    setMode=wrappedSetMode291;
    window.setMode=wrappedSetMode291;
  }

  // Låt valpanelen vara klickbar utan att dokumentets äldre sync-lyssnare tolkar klicket som verktygsbyte.
  OPTION_IDS.forEach(function(id){
    var bind=function(){
      var el=document.getElementById(id); if(!el || el.dataset.tt291Bound)return;
      el.dataset.tt291Bound='1';
      ['pointerdown','mousedown','touchstart','click'].forEach(function(type){
        el.addEventListener(type,function(ev){try{ev.stopPropagation();}catch(e){}},{capture:true,passive:true});
      });
      ['change','input'].forEach(function(type){
        el.addEventListener(type,function(){setTimeout(update291,0);},false);
      });
    };
    if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind);
    else bind();
  });

  document.addEventListener('click',function(ev){
    try{
      if(ev && ev.target && ev.target.closest && ev.target.closest('#arrow-options,#freehand-options,#zone-options'))return;
    }catch(e){}
    setTimeout(schedule291,0);
  },true);
  window.addEventListener('resize',function(){setTimeout(schedule291,80);});
  document.addEventListener('fullscreenchange',schedule291);
  document.addEventListener('webkitfullscreenchange',schedule291);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',schedule291);
  else schedule291();
  setTimeout(schedule291,300);
  setTimeout(schedule291,1000);
  setTimeout(setVersion291,2400);

  window.tt291UpdateDrawOptionsPlacement=update291;
})();
