    try{window.location.href='mailto:'+encodeURIComponent(email)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);}catch(e){try{showToast('Kunde inte öppna mejlprogram',false);}catch(_e){}}
