  function cleanButtons(){try{document.querySelectorAll('#taktik-list.tt374-team-list .tt374-action').forEach(function(b){Array.from(b.childNodes).forEach(function(n){if(n.nodeType!==3)b.removeChild(n);});});}catch(e){}}
