      if(!k||k.charAt(0)==='_')return;
      if(k==='createdAt'||k==='updatedAt'||k==='savedAt'||k==='ts')return;
      var v=obj[k];
      if(typeof v==='function'||typeof v==='undefined')return;
      out[k]=cleanForCompare(v);
